CREATE TABLE IF NOT EXISTS market_offers (id BIGSERIAL PRIMARY KEY, merchant TEXT NOT NULL, market TEXT NOT NULL, external_id TEXT NOT NULL, title TEXT NOT NULL, product_url TEXT NOT NULL, currency TEXT NOT NULL, price NUMERIC, available BOOLEAN, stock_quantity INTEGER, stock_note TEXT, language TEXT NOT NULL DEFAULT 'No determinado', product_kind TEXT, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), verification TEXT NOT NULL DEFAULT 'source_api', UNIQUE(merchant,external_id))